document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('loginForm');const email=document.getElementById('loginEmail');const password=document.getElementById('loginPassword');const emailError=document.getElementById('loginEmailError');const passwordError=document.getElementById('loginPasswordError');function isValidEmail(value){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)}
form.addEventListener('submit',(e)=>{let valid=!0;if(!email.value.trim()){emailError.textContent='يرجى إدخال البريد الإلكتروني';valid=!1}else if(!isValidEmail(email.value.trim())){emailError.textContent='صيغة البريد الإلكتروني غير صحيحة';valid=!1}else{emailError.textContent=''}
if(!password.value){passwordError.textContent='يرجى إدخال كلمة المرور';valid=!1}else{passwordError.textContent=''}
if(!valid){e.preventDefault();return}
const submitBtn=form.querySelector('button[type="submit"]');submitBtn.disabled=!0;submitBtn.textContent='جارِ تسجيل الدخول ...'})})